}

/* ============================================================
   FISHKAL — Audio
   ------------------------------------------------------------
   Fully synthesised. No files, no autoplay, never blocks the UX.
   ============================================================ */

(function () {
  'use strict';

  const Audio_ = {
    ac: null,
    master: null,
    ambGain: null,
    on: false,
    ready: false,

    /* ------------------------------------------------------
       INIT — creates the AudioContext and ambient bed
       ------------------------------------------------------ */
    init() {
      if (this.ac) return;
      try {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return;

        this.ac = new AC();
        this.master = this.ac.createGain();
        this.master.gain.value = 0;
        this.master.connect(this.ac.destination);
        this.ready = true;

        this.ambient();
      } catch (e) {
        this.ready = false;
      }
    },

    /* ------------------------------------------------------
       AMBIENT — filtered noise bed
       ------------------------------------------------------ */
    ambient() {
      try {
        const ac = this.ac;
        const len = ac.sampleRate * 4;
        const buf = ac.createBuffer(1, len, ac.sampleRate);
        const d = buf.getChannelData(0);

        let last = 0;
        for (let i = 0; i < len; i++) {
          const w = Math.random() * 2 - 1;
          last = (last + 0.02 * w) / 1.02;
          d[i] = last * 3.2;
        }

        const src = ac.createBufferSource();
        src.buffer = buf;
        src.loop = true;

        const f = ac.createBiquadFilter();
        f.type = 'lowpass';
        f.frequency.value = 520;
        f.Q.value = 0.6;

        const lfo = ac.createOscillator();
        lfo.frequency.value = 0.06;

        const lg = ac.createGain();
        lg.gain.value = 220;

        lfo.connect(lg);
        lg.connect(f.frequency);

        this.ambGain = ac.createGain();
        this.ambGain.gain.value = 0.5;

        src.connect(f);
        f.connect(this.ambGain);
        this.ambGain.connect(this.master);
        src.start();
        lfo.start();
      } catch (e) {}
    },

    /* ------------------------------------------------------
       TOGGLE — must be called from a user gesture
       ------------------------------------------------------ */
    toggle() {
      this.init();
      if (!this.ready) return false;

      this.on = !this.on;

      try {
        if (this.ac.state === 'suspended') this.ac.resume();
        this.master.gain.cancelScheduledValues(this.ac.currentTime);
        this.master.gain.setTargetAtTime(this.on ? 0.36 : 0, this.ac.currentTime, 0.4);
      } catch (e) {}

      try { localStorage.setItem('fk_sound', this.on ? '1' : '0'); } catch (e) {}

      return this.on;
    },

    /* ------------------------------------------------------
       TONE — simple oscillator with envelope
       ------------------------------------------------------ */
    tone(freq, dur, type, vol, slide) {
      if (!this.on || !this.ready) return;
      try {
        const ac = this.ac;
        const t = ac.currentTime;

        const o = ac.createOscillator();
        const g = ac.createGain();

        o.type = type || 'sine';
        o.frequency.setValueAtTime(freq, t);
        if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t + dur);

        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(vol || 0.14, t + 0.012);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);

        o.connect(g);
        g.connect(this.master);

        o.start(t);
        o.stop(t + dur + 0.05);
      } catch (e) {}
    },

    /* ------------------------------------------------------
       NOISE — filtered burst
       ------------------------------------------------------ */
    noise(dur, freq, q, vol) {
      if (!this.on || !this.ready) return;
      try {
        const ac = this.ac;
        const t = ac.currentTime;
        const len = Math.ceil(ac.sampleRate * dur);
        const b = ac.createBuffer(1, len, ac.sampleRate);
        const d = b.getChannelData(0);

        for (let i = 0; i < len; i++) {
          d[i] = (Math.random() * 2 - 1) * (1 - i / len);
        }

        const s = ac.createBufferSource();
        s.buffer = b;

        const f = ac.createBiquadFilter();
        f.type = 'bandpass';
        f.frequency.value = freq;
        f.Q.value = q || 1;

        const g = ac.createGain();
        g.gain.value = vol || 0.2;

        s.connect(f);
        f.connect(g);
        g.connect(this.master);
        s.start(t);
      } catch (e) {}
    },

    /* ------------------------------------------------------
       SFX PRESETS
       ------------------------------------------------------ */
    splash() {
      this.noise(0.55, 900, 0.7, 0.26);
      this.noise(0.9, 240, 0.9, 0.16);
    },

    tick() {
      this.tone(1180, 0.06, 'sine', 0.10);
    },

    strike() {
      this.tone(660, 0.09, 'triangle', 0.09);
    },

    catchGood() {
      [587.33, 880, 1174.66].forEach((f, i) => {
        setTimeout(() => this.tone(f, 0.7, 'sine', 0.11), i * 110);
      });
      this.noise(0.4, 600, 0.8, 0.2);
    },

    escape() {
      this.tone(320, 0.5, 'sine', 0.07, 180);
      this.noise(0.7, 300, 0.6, 0.1);
    },

    signature() {
      [293.66, 440, 587.33, 880].forEach((f, i) => {
        setTimeout(() => this.tone(f, 1.9, 'sine', 0.055), i * 160);
      });
    }
  };

  /* ------------------------------------------------------
     EXPORT
     ------------------------------------------------------ */
  window.Audio_ = Audio_;

})();

/* ============================================================
   FISHKAL — Fish Rendering
   ------------------------------------------------------------
   Two base body shapes (A and B), two extended (C and D),
   species differ by silhouette, scale, tint and pattern.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     BODY PATHS
     ---------------------------------------------------------- */

  function fishBody(g, type) {
    g.beginPath();

    if (type === 'A') {
      g.moveTo(102, 0);
      g.bezierCurveTo(82, -42, 16, -58, -44, -36);
      g.bezierCurveTo(-72, -27, -90, -16, -104, -9);
      g.lineTo(-104, 9);
      g.bezierCurveTo(-90, 16, -72, 27, -44, 36);
      g.bezierCurveTo(16, 54, 82, 40, 102, 0);
    } else if (type === 'C') {
      g.moveTo(96, 0);
      g.bezierCurveTo(80, -52, 10, -70, -40, -52);
      g.bezierCurveTo(-78, -38, -96, -16, -104, -8);
      g.lineTo(-104, 8);
      g.bezierCurveTo(-96, 16, -78, 38, -40, 52);
      g.bezierCurveTo(10, 70, 80, 52, 96, 0);
    } else if (type === 'D') {
      g.moveTo(118, 0);
      g.bezierCurveTo(96, -30, 26, -42, -46, -30);
      g.bezierCurveTo(-76, -24, -94, -14, -104, -8);
      g.lineTo(-104, 8);
      g.bezierCurveTo(-94, 14, -76, 24, -46, 30);
      g.bezierCurveTo(26, 42, 96, 30, 118, 0);
    } else {
      /* type B */
      g.moveTo(134, 0);
      g.bezierCurveTo(104, -20, 34, -31, -40, -21);
      g.bezierCurveTo(-72, -17, -92, -12, -104, -7);
      g.lineTo(-104, 7);
      g.bezierCurveTo(-92, 12, -72, 17, -40, 21);
      g.bezierCurveTo(34, 31, 104, 20, 134, 0);
    }

    g.closePath();
  }

  function fishTail(g, type) {
    g.beginPath();

    if (type === 'A') {
      g.moveTo(-100, -10);
      g.lineTo(-152, -40);
      g.quadraticCurveTo(-140, 0, -152, 40);
      g.lineTo(-100, 10);
    } else if (type === 'C') {
      g.moveTo(-98, -10);
      g.quadraticCurveTo(-152, -36, -146, 0);
      g.quadraticCurveTo(-152, 36, -98, 10);
    } else if (type === 'D') {
      g.moveTo(-100, -8);
      g.lineTo(-166, -54);
      g.quadraticCurveTo(-124, -6, -166, 54);
      g.lineTo(-100, 8);
    } else {
      g.moveTo(-100, -8);
      g.lineTo(-158, -46);
      g.quadraticCurveTo(-118, 0, -158, 46);
      g.lineTo(-100, 8);
    }

    g.closePath();
  }

  /* ----------------------------------------------------------
     FISH DRAWING
     ---------------------------------------------------------- */

  function drawFish(f, t) {
    const ctx = window.ctx;
    const sp = f.sp;
    const s = f.scale * f.baseScale;
    if (s <= 0.001) return;

    ctx.save();
    ctx.globalAlpha = f.alpha;
    ctx.translate(f.x, f.y);
    ctx.rotate(f.rot);
    ctx.scale(s * f.dir, s);

    const sway = Math.sin(t * f.beat + f.phase);
    ctx.rotate(sway * 0.045);

    /* Tail hinged at the peduncle */
    ctx.save();
    ctx.translate(-100, 0);
    ctx.rotate(Math.sin(t * f.beat + f.phase - 0.7) * 0.34);
    ctx.translate(100, 0);
    fishTail(ctx, sp.type);
    ctx.fillStyle = 'rgba(5,22,28,.82)';
    ctx.fill();
    ctx.restore();

    /* Pectoral fin */
    ctx.save();
    ctx.translate(34, 14);
    ctx.rotate(0.5 + sway * 0.22);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(-22, 20, -44, 10);
    ctx.quadraticCurveTo(-24, 4, 0, 0);
    ctx.fillStyle = 'rgba(6,26,32,.7)';
    ctx.fill();
    ctx.restore();

    /* Body */
    fishBody(ctx, sp.type);
    const lg = ctx.createLinearGradient(0, -58, 0, 54);
    lg.addColorStop(0,    sp.tint);
    lg.addColorStop(0.30, '#0a2630');
    lg.addColorStop(1,    '#03131a');
    ctx.fillStyle = lg;
    ctx.fill();

    /* Detail inside clip */
    ctx.save();
    ctx.clip();

    const rg = ctx.createLinearGradient(0, -60, 0, -8);
    rg.addColorStop(0, 'rgba(255,214,158,.40)');
    rg.addColorStop(1, 'rgba(255,214,158,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(-170, -60, 340, 60);

    if (sp.pat === 'bars') {
      ctx.fillStyle = 'rgba(4,18,24,.5)';
      for (let i = 0; i < 5; i++) {
        const x = -64 + i * 34;
        ctx.beginPath();
        ctx.ellipse(x, 0, 7, Math.max(10, 44 - Math.abs(x) / 3), 0, 0, TAU);
        ctx.fill();
      }
    }

    if (sp.pat === 'spots') {
      ctx.fillStyle = 'rgba(214,178,120,.35)';
      for (let i = 0; i < 14; i++) {
        const x = -80 + ((i * 53) % 160);
        const y = -30 + ((i * 29) % 60);
        ctx.beginPath();
        ctx.arc(x, y, 2.4 + (i % 3), 0, TAU);
        ctx.fill();
      }
    }

    if (sp.pat === 'stripe') {
      ctx.fillStyle = 'rgba(220,190,140,.28)';
      ctx.fillRect(-104, -6, 210, 10);
    }

    if (sp.pat === 'fork') {
      ctx.strokeStyle = 'rgba(210,160,110,.30)';
      ctx.lineWidth = 2 / s;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(-20 + i * 26, -40 + i * 6);
        ctx.quadraticCurveTo(10 + i * 26, 0, -20 + i * 26, 40 - i * 6);
        ctx.stroke();
      }
    }

    ctx.restore();

    /* Rim */
    fishBody(ctx, sp.type);
    ctx.strokeStyle = 'rgba(255,222,176,.30)';
    ctx.lineWidth = 1.6 / s;
    ctx.stroke();

    /* Eye */
    if (s > 0.42) {
      ctx.beginPath();
      ctx.arc(74, -11, 5.5, 0, TAU);
      ctx.fillStyle = 'rgba(3,12,16,.95)';
      ctx.fill();

      ctx.beginPath();
      ctx.arc(75.6, -12.6, 1.8, 0, TAU);
      ctx.fillStyle = 'rgba(255,226,180,.85)';
      ctx.fill();
    }

    ctx.restore();
    ctx.globalAlpha = 1;
  }

  /* ----------------------------------------------------------
     AMBIENT SCHOOL
     ------------------------------------------------------------ */

  const HUES = [
    'rgba(126,178,178,',
    'rgba(158,186,164,',
    'rgba(142,164,196,',
    'rgba(196,178,140,'
  ];

  const SCHOOL = Array.from({ length: 28 }, (_, i) => ({
    x: Math.random(),
    y: 0.5 + Math.random() * 0.45,
    s: 0.6 + Math.random() * 1.1,
    v: (0.018 + Math.random() * 0.05) * (Math.random() < 0.5 ? 1 : -1),
    h: HUES[i % 4],
    ph: Math.random() * 6.28,
    dy: Math.random() * 0.06
  }));

  /* Bioluminescent plankton — the deep answers with its own light */
  const GLOWS = Array.from({ length: 36 }, () => ({
    x: Math.random(),
    y: 0.30 + Math.random() * 0.68,
    v: 0.004 + Math.random() * 0.012,
    r: 1.0 + Math.random() * 2.2,
    sp: 0.4 + Math.random() * 1.2,
    ph: Math.random() * 6.28
  }));

  function drawSchoolFish(g, x, y, s, dir, hue, a, t, ph) {
    g.save();
    g.translate(x, y);
    g.scale(dir * s, s);
    g.globalAlpha = a;

    g.fillStyle = hue + '0.55)';

    g.beginPath();
    g.moveTo(14, 0);
    g.quadraticCurveTo(5, -6.5, -5, -4.5);
    g.quadraticCurveTo(-10, -2.5, -12, 0);
    g.quadraticCurveTo(-10, 2.5, -5, 4.5);
    g.quadraticCurveTo(5, 6.5, 14, 0);
    g.fill();

    g.save();
    g.translate(-11, 0);
    g.rotate(Math.sin(t * 4 + ph) * 0.35);
    g.beginPath();
    g.moveTo(0, 0);
    g.lineTo(-7, -5.5);
    g.quadraticCurveTo(-4.5, 0, -7, 5.5);
    g.closePath();
    g.fill();
    g.restore();

    g.beginPath();
    g.moveTo(3, -4);
    g.quadraticCurveTo(-1, -9.5, -6, -4.5);
    g.closePath();
    g.fill();

    g.beginPath();
    g.moveTo(2, 4);
    g.quadraticCurveTo(-1, 7.5, -5, 4.5);
    g.closePath();
    g.fill();

    g.beginPath();
    g.arc(9, -1.2, 1.15, 0, 7);
    g.fillStyle = 'rgba(3,12,16,.9)';
    g.fill();

    g.beginPath();
    g.arc(9.4, -1.6, 0.4, 0, 7);
    g.fillStyle = 'rgba(230,240,240,.8)';
    g.fill();

    g.restore();
  }

  /* ----------------------------------------------------------
     AMBIENT CANVAS LOOP
     ---------------------------------------------------------- */

  let ambCanvas = null;
  let ambCtx = null;
  let AW = 0;
  let AH = 0;

  function initAmbient() {
    ambCanvas = document.createElement('canvas');
    ambCanvas.id = 'amb';
    document.body.appendChild(ambCanvas);
    ambCtx = ambCanvas.getContext('2d');
    ambSize();
    window.addEventListener('resize', ambSize, { passive: true });
    requestAnimationFrame(ambLoop);
  }

  function ambSize() {
    const d = Math.min(2, window.devicePixelRatio || 1);
    AW = ambCanvas.width = window.innerWidth * d;
    AH = ambCanvas.height = window.innerHeight * d;
  }

  function ambLoop() {
    requestAnimationFrame(ambLoop);

    const c = window.cam;
    if (!c) return;
    const d = c.depth;
    const a = Math.max(0, Math.min(1, (d - 0.3) * 2));

    if (a <= 0.01) {
      ambCtx.clearRect(0, 0, AW, AH);
      return;
    }

    const t = performance.now() / 1000;
    ambCtx.clearRect(0, 0, AW, AH);

    const dpr = Math.min(2, window.devicePixelRatio || 1);

    for (const f of SCHOOL) {
      f.x += f.v * 0.016;
      if (f.x > 1.15) f.x = -0.15;
      if (f.x < -0.15) f.x = 1.15;
      const y = (f.y + Math.sin(t * 0.5 + f.ph) * f.dy) * AH;
      drawSchoolFish(
        ambCtx,
        f.x * AW,
        y,
        f.s * dpr * 3.2,
        f.v > 0 ? 1 : -1,
        f.h,
        a * (0.35 + f.s * 0.3),
        t,
        f.ph
      );
    }

    /* Bioluminescence below mid-depth */
    if (d > 0.5) {
      ambCtx.globalCompositeOperation = 'lighter';
      const ga = Math.min(1, (d - 0.5) * 2.4);
      for (const gd of GLOWS) {
        gd.y -= gd.v * 0.016;
        if (gd.y < -0.02) { gd.y = 1.02; gd.x = Math.random(); }
        const fl = Math.max(0, Math.sin(t * gd.sp + gd.ph));
        const a2 = ga * fl * 0.5;
        if (a2 < 0.02) continue;
        ambCtx.fillStyle = `rgba(124,240,220,${a2.toFixed(3)})`;
        ambCtx.beginPath();
        ambCtx.arc(gd.x * AW, gd.y * AH, gd.r * (0.6 + fl) * dpr, 0, 6.2832);
        ambCtx.fill();
      }
      ambCtx.globalCompositeOperation = 'source-over';
    }
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.fishBody = fishBody;
  window.fishTail = fishTail;
  window.drawFish = drawFish;
  window.initAmbient = initAmbient;

})();

/* ============================================================
   FISHKAL — Game
   ------------------------------------------------------------
   One skill: timing. No score, no counters, no failure language.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     CAMERA SHAKE
     ---------------------------------------------------------- */

  let shakeAmt = 0;
  let shakeUntil = 0;

  function shake(a, ms) {
    if (window.isReduced()) return;
    shakeAmt = a;
    shakeUntil = performance.now() + ms;
  }

  function getShake() {
    if (performance.now() >= shakeUntil) return 0;
    return shakeAmt;
  }

  /* ----------------------------------------------------------
     GAME STATE MACHINE
     ---------------------------------------------------------- */

  const Game = {
    state: 'IDLE',
    armed: false,
    sp: null,
    fish: null,

    tLock: 0,
    tCast: 0,
    tApp: 0,
    tAppEnd: 0,
    tWinEnd: 0,
    tGrace: 0,
    tEnd: 0,
    tFreeze: 0,

    kind: null,
    perfect: false,
    cued: false,
    anim: 0,

    /* ------------------------------------------------------
       RESET
       ------------------------------------------------------ */
    reset() {
      this.state = 'IDLE';
      this.armed = false;
      this.sp = null;
      this.fish = null;
      this.kind = null;
      this.perfect = false;
      this.anim = 0;

      const h = window.hook;
      if (h) {
        h.tremor = 1.4;
        h.freq = 9;
      }

      const gSonar = window.gSonar;
      const gHalo = window.gHalo;
      if (gSonar) gSonar.setAttribute('opacity', '0');
      if (gHalo) gHalo.setAttribute('opacity', '0');

      const ui = window.ui;
      if (ui) {
        if (ui.result) ui.result.classList.remove('on');
        if (ui.cue) ui.cue.style.opacity = '0';
      }

      const strikeBtn = document.getElementById('strike');
      if (strikeBtn) {
        strikeBtn.classList.remove('live');
        strikeBtn.disabled = true;
      }
    },

    /* ------------------------------------------------------
       SPECIES PICK
       ------------------------------------------------------ */
    pick() {
      const total = window.SPECIES.reduce((sum, s) => sum + s.weight, 0);
      let r = Math.random() * total;
      let acc = 0;
      for (const s of window.SPECIES) {
        acc += s.weight;
        if (r <= acc) return s;
      }
      return window.SPECIES[0];
    },

    /* ------------------------------------------------------
       ARM — trigger when camera has settled
       ------------------------------------------------------ */
    arm(now) {
      if (this.armed) return;
      this.armed = true;
      this.tLock = now;
      this.state = 'IDLE';
    },

    /* ------------------------------------------------------
       CAST
       ------------------------------------------------------ */
    cast(now) {
      this.state = 'CAST';
      this.tCast = now;

      const h = window.hook;
      if (h && window.spawnBubbles) {
        window.spawnBubbles(h.x, h.y, 18, 1.4);
      }
      window.Audio_.splash();
      shake(2, 300);
    },

    /* ------------------------------------------------------
       APPROACH
       ------------------------------------------------------ */
    approach(now) {
      this.state = 'APPROACH';
      const sp = this.pick();
      this.sp = sp;

      const W = window.W;
      const H = window.H;
      const dir = Math.random() < 0.5 ? 1 : -1;
      const base = (Math.min(W, H) / 640) * sp.scale;

      this.tApp = now;
      this.tAppEnd = now + sp.approach;

      this.fish = {
        sp,
        dir,
        baseScale: base,
        scale: 0.06,
        alpha: 0,
        rot: 0,
        x: dir > 0 ? -W * 0.30 : W * 1.30,
        y: H * 0.80,
        sx: dir > 0 ? -W * 0.30 : W * 1.30,
        sy: H * 0.80,
        phase: Math.random() * TAU,
        beat: sp.type === 'B' ? 7.6 : 4.7
      };

      const strikeBtn = document.getElementById('strike');
      if (strikeBtn) {
        strikeBtn.classList.add('live');
        strikeBtn.disabled = false;
        try { strikeBtn.focus({ preventScroll: true }); } catch (e) {}
      }

      const ui = window.ui;
      if (ui && ui.cue && !this.cued) {
        this.cued = true;
        ui.cue.style.opacity = '1';
      }

      const gSonar = window.gSonar;
      if (gSonar) gSonar.setAttribute('opacity', '1');
    },

    /* ------------------------------------------------------
       OPEN WINDOW
       ------------------------------------------------------ */
    openWindow(now) {
      this.state = 'STRIKE_WINDOW';
      this.tWinEnd = now + window.GAME.strikeWindow;
      this.tGrace = this.tWinEnd + window.GAME.grace;

      const gHalo = window.gHalo;
      if (gHalo) gHalo.setAttribute('opacity', '1');

      window.Audio_.strike();
    },

    /* ------------------------------------------------------
       TAP
       ------------------------------------------------------ */
    tap(now) {
      if (this.state === 'APPROACH') {
        /* Early taps are never punished — the hook just twitches */
        const h = window.hook;
        if (h) h.tremor = Math.min(h.tremor + 4, 16);
        window.Audio_.tick();
        return;
      }

      if (this.state !== 'STRIKE_WINDOW') return;

      const centre = this.tWinEnd - window.GAME.strikeWindow / 2;
      this.perfect = Math.abs(now - centre) <= window.GAME.perfect;
      this.land(now);
    },

    /* ------------------------------------------------------
       LAND — catch!
       ------------------------------------------------------ */
    land(now) {
      this.state = 'CATCH';
      this.kind = 'CATCH';
      this.tFreeze = now + window.GAME.freezeMs;
      this.tEnd = now + 1150;

      const gHalo = window.gHalo;
      const gSonar = window.gSonar;
      if (gHalo) gHalo.setAttribute('opacity', '0');
      if (gSonar) gSonar.setAttribute('opacity', '0');

      const strikeBtn = document.getElementById('strike');
      if (strikeBtn) {
        strikeBtn.classList.remove('live');
        strikeBtn.disabled = true;
      }

      const h = window.hook;
      if (h) window.spawnBubbles(h.x, h.y, 22, 1.8);

      window.Audio_.catchGood();
      shake(3, 180);

      if (window.track) {
        window.track('catch', { species: this.sp ? this.sp.id : '', perfect: this.perfect });
      }
    },

    /* ------------------------------------------------------
       LOSE — escaped
       ------------------------------------------------------ */
    lose(now) {
      this.state = 'ESCAPED';
      this.kind = 'ESCAPED';
      this.tEnd = now + 1500;

      if (this.fish) this.fish.dir *= -1;

      const gHalo = window.gHalo;
      const gSonar = window.gSonar;
      if (gHalo) gHalo.setAttribute('opacity', '0');
      if (gSonar) gSonar.setAttribute('opacity', '0');

      const strikeBtn = document.getElementById('strike');
      if (strikeBtn) {
        strikeBtn.classList.remove('live');
        strikeBtn.disabled = true;
      }

      const h = window.hook;
      if (h) window.spawnBubbles(h.x, h.y, 8, 0.7);

      window.Audio_.escape();

      if (window.track) window.track('escape');
    },

    /* ------------------------------------------------------
       SHOW RESULT CARD
       ------------------------------------------------------ */
    show() {
      this.state = 'RESULT_SHOWN';
      this.tEnd = performance.now() + 2100;

      const ui = window.ui;
      if (ui && ui.cue) ui.cue.style.opacity = '0';
      if (!ui || !ui.result) return;

      const r = ui.result;
      const T = window.T;

      if (this.kind === 'CATCH') {
        r.querySelector('.kicker').textContent = T(this.perfect ? 'Clean strike' : 'Landed');
        r.querySelector('.name').textContent = T(this.sp.id);
        r.querySelector('.latin').textContent = this.sp.latin;
        r.querySelector('.line').textContent = T(this.sp.line);
      } else {
        r.querySelector('.kicker').textContent = T('The line went slack');
        r.querySelector('.name').textContent = T('Still out there');
        r.querySelector('.latin').textContent = '';
        r.querySelector('.line').textContent = T('A fish is still on its way.');
      }

      r.classList.add('on');
      window.Audio_.signature();
    },

    /* ------------------------------------------------------
       UPDATE — called every frame
       ------------------------------------------------------ */
    update(now, dt, t) {
      if (!this.armed) return;

      const W = window.W;
      const H = window.H;
      const G = window.GAME;
      const h = window.hook;

      switch (this.state) {

        case 'IDLE':
          if (h) h.tremor = damp(h.tremor, 1.4, 4, dt);
          if (now - this.tLock > G.settleMs) this.cast(now);
          break;

        case 'CAST':
          if (h) h.tremor = damp(h.tremor, 2.2, 3, dt);
          if (now - this.tCast > G.castMs) this.approach(now);
          break;

        case 'APPROACH': {
          const f = this.fish;
          const sp = this.sp;
          const q = clamp((now - this.tApp) / sp.approach, 0, 1);
          const e = easeInOut(q);
          const tx = h.x - f.dir * W * 0.13;
          const ty = h.y + H * 0.02;

          f.x = lerp(f.sx, tx, e) + Math.sin(now * 0.0013 + f.phase) * W * 0.014 * (1 - e * 0.6);
          f.y = lerp(f.sy, ty, e) + Math.sin(now * 0.0009 + f.phase * 1.7) * H * 0.016;
          f.scale = lerp(0.06, 1, Math.pow(e, 0.82));
          f.alpha = smoothstep(0, 0.14, q);
          f.rot = Math.sin(now * 0.0011 + f.phase) * 0.05;

          const pre = clamp((now - (this.tAppEnd - 1500)) / 1500, 0, 1);
          h.tremor = lerp(0.6, 8, e) + pre * 7;
          h.freq = lerp(8, 17, pre);
          f.beat = (sp.type === 'B' ? 7.6 : 4.7) + pre * 4;

          if (window.getQuality() >= 2 && Math.random() < 0.04) {
            window.spawnBubbles(f.x, f.y, 1, 0.4);
          }

          if (now >= this.tAppEnd) this.openWindow(now);
          break;
        }

        case 'STRIKE_WINDOW': {
          const f = this.fish;
          const w = clamp((now - (this.tWinEnd - G.strikeWindow)) / G.strikeWindow, 0, 1.2);
          const tx = h.x - f.dir * W * 0.13;
          const ex = h.x - f.dir * W * 0.018;

          f.x = lerp(tx, ex, easeIn(clamp(w, 0, 1)));
          f.scale = lerp(1, 1.1, clamp(w, 0, 1));

          h.tremor = 13;
          h.freq = 21;
          this.anim = w;

          if (now > this.tGrace) this.lose(now);
          break;
        }

        case 'CATCH': {
          const f = this.fish;

          if (now < this.tFreeze) {
            h.tremor = 2;
            break;
          }

          const k = clamp((now - this.tFreeze) / 900, 0, 1);
          f.x = lerp(f.x, h.x - f.dir * W * 0.01, 0.12);
          f.y = lerp(f.y, h.y - H * 0.05 * k, 0.10);
          f.rot = lerp(f.rot, -f.dir * 0.5, 0.06);
          f.alpha = 1 - smoothstep(0.55, 1, k);
          h.tremor = damp(h.tremor, 1.6, 3, dt);

          if (now > this.tEnd) this.show();
          break;
        }

        case 'ESCAPED': {
          const f = this.fish;
          const k = clamp((now - (this.tEnd - 1500)) / 1500, 0, 1);

          f.x += f.dir * W * 0.35 * dt;
          f.y -= H * 0.04 * dt;
          f.scale = lerp(1, 0.35, k);
          f.alpha = 1 - smoothstep(0.45, 1, k);
          f.rot = lerp(f.rot, 0, 0.05);
          h.tremor = damp(h.tremor, 1.2, 3, dt);

          if (now > this.tEnd) this.show();
          break;
        }

        case 'RESULT_SHOWN':
          if (h) h.tremor = damp(h.tremor, 1.2, 3, dt);
          if (now > this.tEnd) {
            this.state = 'UNLOCK';
            window.unlockScroll();
          }
          break;

        case 'UNLOCK':
          if (h) h.tremor = damp(h.tremor, 1.2, 3, dt);
          break;
      }

      /* Sonar update */
      if (this.state === 'APPROACH') {
        const gSonar = window.gSonar;
        if (gSonar) {
          const transform = `translate(${h.x.toFixed(1)}px,${h.y.toFixed(1)}px)`;
          gSonar.style.transform = transform;

          const base = Math.min(W, H);
          const pulse = (t * 0.45) % 1;
          const r1 = base * 0.06 * (0.6 + pulse * 0.9) / 52;
          const r2 = base * 0.11 * (0.6 + pulse * 0.8) / 92;
          const r3 = base * 0.17 * (0.6 + pulse * 0.7) / 140;

          gSonar.children[0].style.transform = `scale(${r1.toFixed(3)})`;
          gSonar.children[1].style.transform = `scale(${r2.toFixed(3)})`;
          gSonar.children[2].style.transform = `scale(${r3.toFixed(3)})`;
          gSonar.children[0].style.transformOrigin = '0 0';
          gSonar.children[1].style.transformOrigin = '0 0';
          gSonar.children[2].style.transformOrigin = '0 0';

          gSonar.setAttribute('opacity', (0.28 + 0.24 * Math.sin(t * 2.4)).toFixed(3));
        }
      }

      /* Halo update */
      if (this.state === 'STRIKE_WINDOW') {
        const gHalo = window.gHalo;
        const halo1 = window.halo1;
        const halo2 = window.halo2;

        if (gHalo && halo1 && halo2) {
          const transform = `translate(${h.x.toFixed(1)}px,${h.y.toFixed(1)}px)`;
          gHalo.style.transform = transform;

          const base = Math.min(W, H) * 0.055;
          const k = clamp(this.anim, 0, 1);

          halo1.setAttribute('r', (base * (0.7 + k * 1.5)).toFixed(1));
          halo2.setAttribute('r', (base * (0.7 + k * 0.9)).toFixed(1));

          gHalo.setAttribute('opacity', (0.9 * (1 - k * 0.55)).toFixed(3));
        }
      }
    }
  };

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.Game = Game;
  window.shake = shake;
  window.getShake = getShake;

})();

/* ============================================================
   FISHKAL — Hero (Above Water)
   ------------------------------------------------------------
   The photographic plate, brought to life:
     • Sea is redrawn slice by slice with travelling displacement
     • Sky and sea extended procedurally beyond the plate
     • Flag rebuilt on its own pole
     • Sun bloom, glitter, foam and bow spray
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     IMAGE LOADING
     ---------------------------------------------------------- */

  const HERO = new Image();
  HERO.decoding = 'async';
  HERO.fetchPriority = 'high';

  let heroReady = false;

  HERO.onload = () => { heroReady = true; };
  HERO.onerror = () => { heroReady = false; };

  /* Prefer AVIF if supported, fall back to WebP */
  const supportsAvif = (() => {
    try {
      const c = document.createElement('canvas');
      return c.toDataURL('image/avif').indexOf('data:image/avif') === 0;
    } catch (e) { return false; }
  })();

  const config = window.FK || {};
  HERO.src = supportsAvif && config.heroAvif
    ? config.heroAvif
    : (config.heroWebp || '/assets/img/hero.webp');

  /* ----------------------------------------------------------
     TRANSFORM STATE
     ---------------------------------------------------------- */

  const heroT = { dx: 0, dy: 0, sc: 1 };

  function heroTransform(p, t) {
    const W = window.W;
    const H = window.H;
    const IW = window.IW;
    const IH = window.IH;
    const IMG = window.IMG;

    /* One slow push-in: wide on the skyline, tight on the vessel,
       then pulled back again for the closing frame.
       On tall screens the frame opens wider than the viewport and
       the sky above and sea below are continued procedurally. */
    const portrait = W / H < 1.1;
    const cover = Math.max(W / IW, H / IH);
    const sc0 = cover;
    const zEnd = portrait ? Math.max(1.5, (H / IH) / sc0 * 1.06) : 1.42;

    let zoom = lerp(1.0, zEnd, easeInOut(smoothstep(0, 0.50, p)));
    zoom *= 1 - 0.24 * smoothstep(0.82, 1, p);

    const sc = sc0 * zoom;
    const fu = lerp(portrait ? 0.365 : 0.500, 0.385, smoothstep(0, 0.50, p));
    const hzT = lerp(portrait ? 0.585 : 0.450, 0.615, smoothstep(0, 0.50, p));

    const reduced = window.isReduced();
    const heave = reduced
      ? 0
      : (Math.sin(t * 0.62) * H * 0.0046 + Math.sin(t * 0.97 + 1.1) * H * 0.0022);

    heroT.sc = sc;
    heroT.dx = clamp(W * 0.5 - fu * IW * sc, Math.min(0, W - IW * sc), 0);

    let dy = H * hzT - IMG.horizon * sc + heave;
    if (IH * sc >= H) dy = clamp(dy, H - IH * sc, 0);
    heroT.dy = dy;
  }

  const i2sx = x => heroT.dx + x * heroT.sc;
  const i2sy = y => heroT.dy + y * heroT.sc;

  /* ----------------------------------------------------------
     HULL PATH (used from below once submerged)
     ---------------------------------------------------------- */

  function boatHullPath(g) {
    g.beginPath();
    g.moveTo(-142, -30);
    g.lineTo(-148, 4);
    g.quadraticCurveTo(-60, 20, 70, 13);
    g.quadraticCurveTo(132, 8, 162, -48);
    g.lineTo(150, -50);
    g.quadraticCurveTo(110, -32, 40, -30);
    g.closePath();
  }

  /* ----------------------------------------------------------
     PLATE
     ---------------------------------------------------------- */

  function drawPlate(t) {
    const ctx = window.ctx;
    const HERO_ = HERO;
    const sc = heroT.sc;
    const dx = heroT.dx;
    const dy = heroT.dy;
    const W = window.W;
    const H = window.H;
    const IW = window.IW;
    const IH = window.IH;
    const IMG = window.IMG;

    const over = Math.max(14 * sc, 10);
    const top = dy;
    const bottom = dy + IH * sc;

    /* Continue the sky upward */
    if (top > 0.5) {
      const SKY = { x: 1150, y: 0, w: 414, h: 356 };
      const drift = (t * 7) % (W * 0.5);

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, -1, W, top + 2);
      ctx.clip();
      ctx.translate(-drift, top);
      ctx.scale(1, -1);
      ctx.drawImage(HERO_, SKY.x, SKY.y, SKY.w, SKY.h, 0, 0, W * 1.5, top);
      ctx.restore();

      const g = ctx.createLinearGradient(0, -1, 0, top + 2);
      g.addColorStop(0,    'rgba(24,57,92,.94)');
      g.addColorStop(0.42, 'rgba(46,88,122,.62)');
      g.addColorStop(0.80, 'rgba(86,126,150,.20)');
      g.addColorStop(1,    'rgba(109,146,162,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, -1, W, top + 3);

      const wg = ctx.createLinearGradient(0, 0, W, 0);
      wg.addColorStop(0, 'rgba(58,96,130,.18)');
      wg.addColorStop(1, 'rgba(210,164,112,.16)');
      ctx.fillStyle = wg;
      ctx.fillRect(0, -1, W, top + 3);

      const merge = Math.min(top * 0.34, 72);
      const steps = 9;
      for (let i = 0; i < steps; i++) {
        const a = Math.pow((i + 1) / steps, 1.7) * 0.92;
        const sg = ctx.createLinearGradient(0, 0, W, 0);
        sg.addColorStop(0,   `rgba(75,127,151,${a})`);
        sg.addColorStop(0.5, `rgba(109,146,162,${a})`);
        sg.addColorStop(1,   `rgba(129,155,166,${a})`);
        ctx.fillStyle = sg;
        ctx.fillRect(0, top - merge + merge * i / steps, W, merge / steps + 1);
      }

      /* A living sky, so a tall portrait frame never falls dead above the
         plate: three drifting cloud veils and a few far birds — procedural. */
      if (top > 40) {
        ctx.save();
        ctx.beginPath(); ctx.rect(0, -1, W, top + 2); ctx.clip();
        const R3 = rng(6180);
        for (let i = 0; i < 3; i++) {
          const cy = top * (0.15 + 0.23 * i) + Math.sin(t * 0.05 + i) * 6;
          const cw = W * (0.45 + R3() * 0.6), ch = Math.max(9, top * 0.07);
          const cx = ((R3() * W + t * 4 * (i + 1)) % (W + cw * 2)) - cw;
          const cg = ctx.createRadialGradient(cx, cy, 0, cx, cy, cw * 0.5);
          cg.addColorStop(0, 'rgba(226,236,244,.10)');
          cg.addColorStop(1, 'rgba(226,236,244,0)');
          ctx.fillStyle = cg;
          ctx.beginPath(); ctx.ellipse(cx, cy, cw * 0.5, ch, 0, 0, TAU); ctx.fill();
        }
        ctx.strokeStyle = 'rgba(12,28,38,.5)'; ctx.lineWidth = 1.4; ctx.lineCap = 'round';
        for (let i = 0; i < 3; i++) {
          const vd = 6 + i * 2.2;
          const bx = ((i * 0.37 * W + t * vd) % (W + 80)) - 40;
          const by = top * 0.60 + Math.sin(t * 0.9 + i * 2.1) * 7 + i * 13;
          const flap = Math.sin(t * (3 + i) + i) * 2.4;
          ctx.beginPath();
          ctx.moveTo(bx - 6, by - flap);
          ctx.quadraticCurveTo(bx - 2, by - 2 - flap, bx, by);
          ctx.quadraticCurveTo(bx + 2, by - 2 - flap, bx + 6, by - flap);
          ctx.stroke();
        }
        ctx.restore();
      }
    }

    /* Sky, skyline and upper works */
    ctx.drawImage(
      HERO_,
      0, 0, IW, IMG.horizon,
      dx, dy, IW * sc, IMG.horizon * sc + 1
    );

    /* Water beside the hull: displaced, hull band untouched */
    const q = window.getQuality();
    const N1 = q >= 2 ? 30 : 12;
    const midH = IMG.hullBottom - IMG.horizon;

    for (let i = 0; i < N1; i++) {
      const v = i / N1;
      const sy = IMG.horizon + midH * v;
      const sh = midH / N1 + 1.2;
      const amp = lerp(0.4, 3.4, v * v) * sc;
      const off = (Math.sin(t * 1.5 + v * 11) + 0.55 * Math.sin(t * 2.6 + v * 19)) * amp;
      const yo = Math.sin(t * 1.1 + v * 8) * amp * 0.45;
      const dyy = dy + sy * sc;

      ctx.drawImage(HERO_, 0, sy, IMG.hullL, sh,
        dx + off - over, dyy + yo, IMG.hullL * sc + over, sh * sc + 1.5);

      ctx.drawImage(HERO_, IMG.hullL, sy, IMG.hullR - IMG.hullL, sh,
        dx + IMG.hullL * sc, dyy, (IMG.hullR - IMG.hullL) * sc, sh * sc + 1.5);

      ctx.drawImage(HERO_, IMG.hullR, sy, IW - IMG.hullR, sh,
        dx + IMG.hullR * sc + off, dyy + yo, (IW - IMG.hullR) * sc + over, sh * sc + 1.5);
    }

    /* Foreground swell */
    const N2 = q >= 2 ? 76 : 28;
    const fgH = IH - IMG.hullBottom;

    for (let i = 0; i < N2; i++) {
      const v = i / N2;
      const sy = IMG.hullBottom + fgH * v;
      const sh = fgH / N2 + 1.2;
      const ramp = smoothstep(0, 0.16, v);
      const amp = lerp(1, 15, v * v) * ramp * sc;
      const off = (
        Math.sin(t * 1.7 + v * 9) +
        0.6 * Math.sin(t * 2.9 + v * 17) +
        0.35 * fbm(v * 6 + t * 0.7, 2)
      ) * amp;
      const yo = Math.sin(t * 1.25 + v * 7) * amp * 0.5;

      ctx.drawImage(HERO_, 0, sy, IW, sh,
        dx + off - over, dy + sy * sc + yo, IW * sc + over * 2, sh * sc + 1.6);
    }

    /* Continue the sea toward the lens */
    if (bottom < H - 0.5) drawNearSea(t, bottom);
  }

  /* ----------------------------------------------------------
     NEAR SEA (below the plate)
     ---------------------------------------------------------- */

  function drawNearSea(t, top) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;
    const q = window.getQuality();
    const span = H - top;

    const g = ctx.createLinearGradient(0, top, 0, H);
    g.addColorStop(0,    'rgb(20,82,86)');
    g.addColorStop(0.45, 'rgb(13,63,71)');
    g.addColorStop(1,    'rgb(5,31,40)');
    ctx.fillStyle = g;
    ctx.fillRect(0, top - 1, W, span + 2);

    const rows = q >= 2 ? 30 : 12;

    for (let i = 0; i <= rows; i++) {
      const tr = i / rows;
      const y = top + span * Math.pow(tr, 1.35);
      const amp = lerp(2, 26, tr);
      const freq = lerp(0.030, 0.007, tr);
      const step = q >= 2 ? 8 : 18;

      ctx.beginPath();
      ctx.moveTo(-10, y + span * 0.06);
      for (let x = -10; x <= W + 10; x += step) {
        ctx.lineTo(x, y + waveAt(x, t + i * 0.23, amp, freq));
      }
      ctx.lineTo(W + 10, y + span * 0.06);
      ctx.closePath();
      ctx.fillStyle = `rgba(4,30,38,${0.05 + 0.05 * tr})`;
      ctx.fill();

      ctx.beginPath();
      for (let x = -10; x <= W + 10; x += step) {
        const yy = y + waveAt(x, t + i * 0.23, amp, freq);
        x === -10 ? ctx.moveTo(x, yy) : ctx.lineTo(x, yy);
      }
      ctx.lineWidth = lerp(1, 3, tr);
      ctx.strokeStyle = `rgba(${lerp(90, 206, tr) | 0},${lerp(170, 224, tr) | 0},${lerp(175, 206, tr) | 0},${lerp(0.06, 0.20, tr)})`;
      ctx.stroke();

      if (tr > 0.25 && q >= 2) {
        ctx.beginPath();
        for (let x = -10; x <= W + 10; x += 11) {
          const w1 = waveAt(x, t + i * 0.23, amp, freq);
          const w2 = waveAt(x + 11, t + i * 0.23, amp, freq);
          if (w2 - w1 > amp * 0.16) {
            ctx.moveTo(x, y + w1);
            ctx.lineTo(x + 10, y + w1 + (w2 - w1) * 0.55);
          }
        }
        ctx.strokeStyle = `rgba(238,250,246,${(tr - 0.25) * 0.34})`;
        ctx.lineWidth = lerp(1, 3.2, tr);
        ctx.stroke();
      }
    }

    const bl = ctx.createLinearGradient(0, top - span * 0.10, 0, top + span * 0.16);
    bl.addColorStop(0,   'rgba(20,82,86,0)');
    bl.addColorStop(0.5, 'rgba(20,82,86,.45)');
    bl.addColorStop(1,   'rgba(20,82,86,0)');
    ctx.fillStyle = bl;
    ctx.fillRect(0, top - span * 0.10, W, span * 0.26);
  }

  /* ----------------------------------------------------------
     LIGHT (sun, glitter, foam)
     ---------------------------------------------------------- */

  function drawLight(t) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;
    const q = window.getQuality();
    const IMG = window.IMG;

    const sx = i2sx(IMG.sunX);
    const sy = i2sy(IMG.sunY);
    const hz = i2sy(IMG.horizon);
    const base = Math.min(W, H);

    ctx.globalCompositeOperation = 'lighter';

    const pulse = 0.86 + 0.14 * Math.sin(t * 0.5) + 0.05 * Math.sin(t * 1.7);
    const rg = ctx.createRadialGradient(sx, sy, 0, sx, sy, base * 0.30);
    rg.addColorStop(0,   `rgba(255,226,166,${0.34 * pulse})`);
    rg.addColorStop(0.45,`rgba(255,196,120,${0.12 * pulse})`);
    rg.addColorStop(1,   'rgba(255,190,120,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(sx - base * 0.32, sy - base * 0.32, base * 0.64, base * 0.64);

    const R = rng(9931);
    const n = q >= 2 ? 150 : 55;
    for (let i = 0; i < n; i++) {
      const u = R(), v = R(), f = R();
      const y = hz + Math.pow(v, 1.9) * (H - hz);
      if (y < hz || y > H) continue;
      const dn = (y - hz) / (H - hz || 1);
      const spread = lerp(W * 0.03, W * 0.30, dn);
      const x = sx + (u - 0.5) * 2 * spread;
      if (x < 0 || x > W) continue;
      const a = Math.max(0, Math.sin(t * (1.6 + f * 3.2) + i * 2.3)) * lerp(0.16, 0.5, dn);
      const w = lerp(2, 15, dn);
      ctx.fillStyle = `rgba(255,${226 - 40 * f | 0},${170 - 50 * f | 0},${a})`;
      ctx.fillRect(x - w / 2, y, w, lerp(1, 2.4, dn));
    }

    const R2 = rng(1279);
    const m = q >= 2 ? 70 : 26;
    const fy = i2sy(IMG.hullBottom);
    for (let i = 0; i < m; i++) {
      const u = R2(), v = R2(), f = R2();
      const y = fy + v * (H - fy);
      if (y < 0 || y > H) continue;
      const a = Math.max(0, Math.sin(t * (2.2 + f * 3.4) + i * 1.7)) * 0.30 * smoothstep(fy, H, y);
      ctx.fillStyle = `rgba(244,252,248,${a})`;
      ctx.fillRect(u * W, y, lerp(2, 9, v), 1.4);
    }

    ctx.globalCompositeOperation = 'source-over';
  }

  /* ----------------------------------------------------------
     FLAG
     ---------------------------------------------------------- */

  function drawFlag(t) {
    const ctx = window.ctx;
    const IMG = window.IMG;
    const hx = IMG.flagX;
    const hy = IMG.flagY;
    const fw = IMG.flagW;
    const fh = IMG.flagH;
    const ang = IMG.flagAng;
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const N = 34;

    function pt(u, v) {
      const amp = 13 * u * u + 3 * u;
      const w = Math.sin(t * 4.1 + u * 7.4) * amp +
                Math.sin(t * 2.5 + u * 4.1) * amp * 0.45;
      const h = fh * lerp(1, 0.78, u);
      return [
        hx + ca * fw * u + 0.08 * h * v + w * 0.18,
        hy + sa * fw * u + h * v + w * 0.92 + u * u * 9
      ];
    }

    function quad(u0, u1, v0, v1, fill) {
      const a = pt(u0, v0);
      const b = pt(u1, v0);
      const c = pt(u1, v1);
      const d = pt(u0, v1);
      ctx.beginPath();
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      ctx.lineTo(c[0], c[1]);
      ctx.lineTo(d[0], d[1]);
      ctx.closePath();
      ctx.fillStyle = fill;
      ctx.fill();
    }

    const bands = [
      [0,     1/3, '#0d8a45'],
      [1/3,   2/3, '#f4f1e8'],
      [2/3,   1,   '#1c1c1c']
    ];

    for (const [v0, v1, col] of bands) {
      for (let i = 8; i < N; i++) quad(i / N, (i + 1.03) / N, v0, v1, col);
    }

    for (let i = 0; i < 9; i++) quad(i / N, (i + 1.03) / N, 0, 1, '#c8102e');

    for (let i = 0; i < N; i++) {
      const u0 = i / N;
      const uc = (i + 0.5) / N;
      const v = Math.sin(t * 4.1 + uc * 7.4);
      const a = Math.abs(v) * 0.22 * (uc * 0.85 + 0.15);
      quad(u0, (i + 1.03) / N, 0, 1,
        v > 0 ? `rgba(255,244,216,${a * 0.85})` : `rgba(0,0,0,${a})`);
    }

    for (let i = 0; i < N; i++) {
      const u0 = i / N;
      const uc = (i + 0.5) / N;
      quad(u0, (i + 1.03) / N, 0, 1,
        `rgba(255,${196 - 30 * uc | 0},${132 - 30 * uc | 0},${0.16 - 0.10 * uc})`);
    }
  }

  /* ----------------------------------------------------------
     SPRAY
     ---------------------------------------------------------- */

  const spray = [];

  function initSpray() {
    spray.length = 0;
    for (let i = 0; i < 80; i++) {
      spray.push({ on: false, x: 0, y: 0, vx: 0, vy: 0, r: 0, a: 0 });
    }
  }

  function emitSpray(x, y, n, power) {
    let made = 0;
    for (let i = 0; i < spray.length && made < n; i++) {
      const s = spray[i];
      if (s.on) continue;
      s.on = true;
      s.x = x;
      s.y = y;
      s.vx = (0.3 + Math.random() * 1.2) * power * window.W * 0.05;
      s.vy = -(0.5 + Math.random()) * power * window.H * 0.09;
      s.r = 1 + Math.random() * 2.8;
      s.a = 0.55 + Math.random() * 0.45;
      made++;
    }
  }

  function updateSpray(dt) {
    for (const s of spray) {
      if (!s.on) continue;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.vy += window.H * 0.45 * dt;
      s.a -= dt * 1.3;
      if (s.a <= 0) s.on = false;
    }
  }

  function drawSpray() {
    const ctx = window.ctx;
    ctx.globalCompositeOperation = 'lighter';
    for (const s of spray) {
      if (!s.on) continue;
      ctx.fillStyle = `rgba(242,252,248,${s.a * 0.5})`;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, TAU);
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';
  }

  /* ----------------------------------------------------------
     MASTER DRAW
     ---------------------------------------------------------- */

  function drawHero(t) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;
    const IMG = window.IMG;

    if (!heroReady) {
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0,    '#14344a');
      g.addColorStop(0.55, '#d9a45c');
      g.addColorStop(1,    '#0a2b33');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
      return;
    }

    drawPlate(t);

    ctx.save();
    ctx.translate(heroT.dx, heroT.dy);
    ctx.scale(heroT.sc, heroT.sc);
    drawFlag(t);
    ctx.restore();

    drawLight(t);

    const reduced = window.isReduced();
    const q = window.getQuality();
    if (!reduced && q >= 2 && Math.random() < 0.5) {
      emitSpray(i2sx(IMG.bowX), i2sy(IMG.bowY), 2, 0.8);
    }

    drawSpray();
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.HERO = HERO;
  window.isHeroReady = () => heroReady;

  window.heroTransform = heroTransform;
  window.i2sx = i2sx;
  window.i2sy = i2sy;
  window.boatHullPath = boatHullPath;
  window.drawPlate = drawPlate;
  window.drawNearSea = drawNearSea;
  window.drawLight = drawLight;
  window.drawFlag = drawFlag;
  window.drawHero = drawHero;

  window.initSpray = initSpray;
  window.emitSpray = emitSpray;
  window.updateSpray = updateSpray;
  window.drawSpray = drawSpray;

  window.heroT = heroT;

})();

/* ============================================================
   FISHKAL — Hook Controller
   ------------------------------------------------------------
   Single SVG object — from the rod tip to the seabed.
   Updates SVG transforms using CSS properties for speed.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     DOM
     ---------------------------------------------------------- */

  const gHook     = document.getElementById('gHook');
  const hookBody  = document.getElementById('hookBody');
  const hookLine  = document.getElementById('hookLine');
  const gSonar    = document.getElementById('gSonar');
  const gHalo     = document.getElementById('gHalo');
  const gHud      = document.getElementById('gHud');
  const halo1     = document.getElementById('halo1');
  const halo2     = document.getElementById('halo2');

  /* ----------------------------------------------------------
     STATE
     ---------------------------------------------------------- */

  const hook = {
    x: 0,
    y: 0,
    s: 0,
    a: 0,
    tremor: 1.4,
    freq: 9
  };

  const lastRod = { x: 0, y: 0 };

  /* Cache for CSS transform to avoid re-layout */
  let lastTransform = '';
  let lastOpacity = -1;

  /* ----------------------------------------------------------
     HELPERS
     ---------------------------------------------------------- */

  function hookTarget() {
    return { x: window.W * 0.5, y: window.H * 0.515 };
  }

  /* ----------------------------------------------------------
     UPDATE
     ---------------------------------------------------------- */

  function updateHook(p, t) {
    const TL = window.TL;
    const cam = window.cam;
    const rodTip = window.rodTip;
    const W = window.W;
    const H = window.H;

    const tg = hookTarget();

    if (rodTip && rodTip.v) {
      lastRod.x = rodTip.x;
      lastRod.y = rodTip.y;
    }

    const rod = {
      x: lastRod.x || W * 0.62,
      y: lastRod.y || H * 0.42
    };

    const smallS = 0.30;

    let a, x, y, s;

    if (p < 0.335) {
      a = 0;
      x = rod.x;
      y = rod.y + 40 * smallS;
      s = smallS;
    } else if (p < TL.DESCENT[0]) {
      a = smoothstep(0.335, 0.375, p);
      x = rod.x;
      y = rod.y + 90 * smallS;
      s = smallS;
    } else {
      const d = easeInOut(smoothstep(TL.DESCENT[0], TL.HOOK[1], p));
      a = 1;
      s = lerp(smallS, 1, d);
      x = lerp(rod.x, tg.x, d);
      y = lerp(rod.y + 90 * smallS, tg.y, d);
    }

    if (p > 0.90) a *= 1 - smoothstep(0.90, 0.95, p);

    const tr = hook.tremor * (1 - smoothstep(0, 0.35, cam.above));
    const dx = Math.sin(t * hook.freq) * tr + Math.sin(t * hook.freq * 2.3) * tr * 0.35;
    const dy = Math.cos(t * hook.freq * 0.8) * tr * 0.4;

    hook.x = x + dx;
    hook.y = y + dy;
    hook.s = s;
    hook.a = a;

    if (Math.abs(a - lastOpacity) > 0.002) {
      gHook.setAttribute('opacity', a.toFixed(3));
      lastOpacity = a;
    }

    if (a <= 0.004) return;

    const sc = s * (Math.min(W, H) / 760) * 1.15;
    const tx = hook.x.toFixed(1);
    const ty = hook.y.toFixed(1);

    const transform = `translate(${tx}px,${ty}px) scale(${sc.toFixed(4)}) translate(-30px,-5px)`;
    if (transform !== lastTransform) {
      hookBody.style.transform = transform;
      hookBody.style.transformOrigin = '0 0';
      lastTransform = transform;
    }

    const topY = -30;
    const bend = Math.sin(t * 0.8) * W * 0.012;
    hookLine.setAttribute('d',
      `M ${(hook.x - bend * 0.4).toFixed(1)} ${topY} ` +
      `Q ${(hook.x + bend).toFixed(1)} ${((topY + hook.y) / 2).toFixed(1)} ` +
      `${hook.x.toFixed(1)} ${hook.y.toFixed(1)}`
    );
  }

  /* ----------------------------------------------------------
     HUD LAYOUT
     ---------------------------------------------------------- */

  function layoutHud() {
    const W = window.W;
    const H = window.H;
    const m = Math.round(Math.min(W, H) * 0.055);
    const L = Math.round(Math.min(W, H) * 0.045);

    const hudTL = document.getElementById('hudTL');
    const hudBR = document.getElementById('hudBR');
    const hudCenter = document.getElementById('hudCenter');

    if (hudTL) hudTL.setAttribute('d', `M ${m} ${m + L} L ${m} ${m} L ${m + L} ${m}`);
    if (hudBR) hudBR.setAttribute('d', `M ${W - m} ${H - m - L} L ${W - m} ${H - m} L ${W - m - L} ${H - m}`);
    if (hudCenter) hudCenter.setAttribute('d',
      `M ${W / 2 - 14} ${H * 0.515} L ${W / 2 - 5} ${H * 0.515} ` +
      `M ${W / 2 + 5} ${H * 0.515} L ${W / 2 + 14} ${H * 0.515}`
    );

    /* Set transform-origin once */
    if (gSonar) {
      gSonar.style.transformOrigin = '0 0';
      gSonar.style.willChange = 'transform, opacity';
    }
    if (gHalo) {
      gHalo.style.transformOrigin = '0 0';
      gHalo.style.willChange = 'transform, opacity';
    }
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.hook = hook;
  window.updateHook = updateHook;
  window.layoutHud = layoutHud;

  window.gSonar = gSonar;
  window.gHalo = gHalo;
  window.halo1 = halo1;
  window.halo2 = halo2;

})();

/* ============================================================
   FISHKAL — Main
   ------------------------------------------------------------
   Orchestrator: camera, render loop, events, boot.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     CAMERA
     ---------------------------------------------------------- */

  const cam = {
    horizonY:   0,
    meniscusY:  0,
    depth:      0,
    sunX:       0,
    sunY:       0,
    hullX:      0,
    hullS:      1,
    above:      1
  };

  window.cam = cam;

  const rodTip = { x: 0, y: 0, v: false };
  window.rodTip = rodTip;

  function updateCamera(p, t) {
    const W = window.W;
    const H = window.H;
    const IMG = window.IMG;
    const TL = window.TL;

    window.heroTransform(p, t);

    cam.horizonY = window.i2sy(IMG.horizon);
    cam.sunX = clamp(window.i2sx(IMG.sunX), W * 0.14, W * 0.86);
    cam.sunY = window.i2sy(IMG.sunY);
    cam.hullX = window.i2sx(IMG.hullCx);
    cam.hullS = ((IMG.hullR - IMG.hullL) / 310) * window.heroT.sc;

    rodTip.x = window.i2sx(IMG.rodX);
    rodTip.y = window.i2sy(IMG.rodY);
    rodTip.v = true;

    if (p < TL.DESCENT[0]) {
      cam.meniscusY = H * 1.6;
    } else {
      const d = smoothstep(TL.DESCENT[0], TL.HOOK[0], p);
      cam.meniscusY = lerp(H * 1.35, -H * 0.28, easeInOut(d));
    }

    if (p > TL.ASCENT[0]) {
      const a = smoothstep(0.80, 0.925, p);
      if (a > 0) cam.meniscusY = lerp(-H * 0.28, H * 1.5, easeInOut(a));
    }

    cam.depth = p <= TL.LOCK
      ? smoothstep(0.50, 0.60, p)
      : 1 - smoothstep(0.655, 0.885, p);

    cam.above = clamp(cam.meniscusY / H, 0, 1);
  }

  /* ----------------------------------------------------------
     RENDER
     ---------------------------------------------------------- */

  function render(t) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;

    ctx.setTransform(window.DPR, 0, 0, window.DPR, 0, 0);
    ctx.fillStyle = '#02090d';
    ctx.fillRect(0, 0, W, H);

    ctx.save();

    /* Camera shake */
    if (window.getShake) {
      const s = window.getShake();
      if (s > 0) {
        ctx.translate((Math.random() - 0.5) * s * 2, (Math.random() - 0.5) * s * 2);
      }
    }

    const my = cam.meniscusY;

    /* Underwater layer */
    if (my < H + 30) {
      ctx.save();
      window.waterlinePath(my, t, false);
      ctx.clip();
      window.drawUnderwater(t);
      if (cam.depth > 0.02) window.drawParticles(t);
      if (window.Game && window.Game.fish && window.Game.fish.alpha > 0.004) {
        window.drawFish(window.Game.fish, t);
      }
      ctx.restore();
    }

    /* Above water layer */
    if (my > -30) {
      ctx.save();
      window.waterlinePath(my, t, true);
      ctx.clip();
      window.drawHero(t);
      ctx.restore();
    }

    window.drawMeniscus(t);
    ctx.restore();

    /* Grain */
    const q = window.getQuality();
    if (q >= 2) {
      const grain = window.getGrain();
      if (grain) {
        ctx.save();
        ctx.globalAlpha = 0.055;
        const reduced = window.isReduced();
        const ox = reduced ? 0 : -(Math.random() * 128 | 0);
        const oy = reduced ? 0 : -(Math.random() * 128 | 0);
        ctx.translate(ox, oy);
        ctx.fillStyle = grain;
        ctx.fillRect(0, 0, W + 130, H + 130);
        ctx.restore();
      }
    } else if (q === 1) {
      const grainLayer = window.getGrainLayer();
      if (grainLayer) {
        ctx.save();
        ctx.globalAlpha = 0.045;
        ctx.drawImage(
          grainLayer,
          -(Math.random() * 30 | 0),
          -(Math.random() * 30 | 0)
        );
        ctx.restore();
      }
    }

    /* Vignette */
    const vig = window.getVig();
    if (vig) ctx.drawImage(vig, 0, 0, W, H);
  }

  /* ----------------------------------------------------------
     LOOP
     ---------------------------------------------------------- */

  let last = 0;
  let frames = 0;
  let ft = 0;
  let slow = 0;
  let running = true;
  let rafId = 0;
  let T0 = 0;

  function frame(now) {
    rafId = requestAnimationFrame(frame);
    if (!running) return;

    const dt = Math.min((now - (last || now)) / 1000, 0.05);
    last = now;
    const t = now / 1000;

    if (!T0) T0 = now;

    window.readScroll();

    const rawP = window.rawP;
    const lambda = (rawP > 0.42 && rawP < 0.63) ? 2.3 : 5.0;
    const P = window.isReduced()
      ? rawP
      : window.damp(window.P, rawP, lambda, dt);
    window.P = P;

    /* Arm the game on the settled camera */
    if (window.isLocked() && P >= window.TL.LOCK - 0.003) {
      window.Game.arm(now);
    }

    updateCamera(P, t);
    window.updateHook(P, t);
    window.Game.update(now, dt, t);
    window.updateParticles(dt, t);
    window.updateSpray(dt);
    render(t);
    window.updateUI(P);

    /* Adaptive quality */
    frames++;
    ft += dt;
    if (ft >= 0.5) {
      const fps = frames / ft;
      const q = window.getQuality();

      if (fps < 48 && q > 1) {
        window.setQuality(1);
        window.setSize();
        window.initParticles();
        window.initSpray();
      } else if (fps < 32 && q > 0) {
        window.setQuality(0);
        window.setSize();
      } else if (fps > 58 && q < 2) {
        window.setQuality(2);
        window.setSize();
        window.initParticles();
        window.initSpray();
      }

      frames = 0;
      ft = 0;
    }
  }

  /* ----------------------------------------------------------
     EVENTS
     ---------------------------------------------------------- */

  let resizeT = 0;

  function onResize() {
    clearTimeout(resizeT);
    resizeT = setTimeout(() => {
      window.setSize();
      window.initParticles();
      window.initSpray();
    }, 120);
  }

  window.addEventListener('resize', onResize, { passive: true });
  window.addEventListener('orientationchange', onResize, { passive: true });
  window.addEventListener('scroll', window.readScroll, { passive: true });

  document.addEventListener('visibilitychange', () => {
    running = !document.hidden;
    last = 0;

    if (!running && window.Audio_.ac && window.Audio_.on) {
      try { window.Audio_.ac.suspend(); } catch (e) {}
    } else if (window.Audio_.ac && window.Audio_.on) {
      try { window.Audio_.ac.resume(); } catch (e) {}
    }
  });

  /* Strike handler */
  function doStrike(e) {
    if (e) e.preventDefault();
    window.Audio_.init();
    window.Game.tap(performance.now());
    if (window.track) window.track('strike');
  }

  const strikeBtn = document.getElementById('strike');
  if (strikeBtn) {
    strikeBtn.addEventListener('pointerdown', doStrike);
    strikeBtn.addEventListener('click', e => e.preventDefault());
  }

  window.addEventListener('keydown', e => {
    if (e.key === 'Escape' && window.Game && window.Game.state === 'RESULT_SHOWN') {
      e.preventDefault();
      if (window.dismissResult) window.dismissResult('esc');
      return;
    }
    if ((e.key === ' ' || e.key === 'Enter') &&
        strikeBtn && strikeBtn.classList.contains('live')) {
      e.preventDefault();
      doStrike();
    }
  });

  /* Sound toggle */
  const soundBtn = document.getElementById('sound');
  if (soundBtn) {
    soundBtn.addEventListener('click', () => {
      const on = window.Audio_.toggle();
      soundBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
      soundBtn.setAttribute('aria-label', on ? 'Turn sound off' : 'Turn sound on');
    });
  }

  /* CTA restart */
  const cta = document.getElementById('cta');
  if (cta) {
    cta.addEventListener('click', () => {
      window.Audio_.signature();
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setTimeout(() => {
        window.Game.reset();
        window.Game.cued = false;
        window.Game.armed = false;   /* re-arm on next settled camera */
        window.lockScroll();         /* re-engage the game lock */
        window.P = 0;
        window.rawP = 0;
      }, 700);
    });
  }

  /* Service worker */
  function registerSW() {
    if (!('serviceWorker' in navigator)) return;
    if (!window.FK || !window.FK.enableSW) return;
    if (location.protocol !== 'https:') return;

    navigator.serviceWorker.register('/sw.js').catch(() => {});
  }

  /* ----------------------------------------------------------
     BOOT
     ---------------------------------------------------------- */

  function boot() {
    window.setSize();
    window.initParticles();
    window.initSpray();
    window.initResultDismiss();
    window.initDepthVeil();
    window.initBootScreen();
    window.initAmbient();
    window.initAnalytics();
    window.Game.reset();

    /* live countdown chip (tickCd is defined in i18n.js) */
    if (window.tickCd) {
      window.tickCd();
      setInterval(() => window.tickCd(), 30000);
    }

    try {
      if (localStorage.getItem('fk_sound') === '1') {
        /* Preference is stored; user must still click sound to unlock */
      }
    } catch (e) {}

    if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
    window.scrollTo(0, 0);

    window.readScroll();
    window.P = window.rawP;
    T0 = performance.now();
    updateCamera(window.P, 0);

    rafId = requestAnimationFrame(frame);

    registerSW();

    if (window.track) window.track('start');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }

})();

/* ============================================================
   FISHKAL — Motion & Math Utilities
   ------------------------------------------------------------
   Pure functions. No DOM. No state (except the sine LUT).
   Attached to window.* for use by other modules.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     BASIC MATH
     ---------------------------------------------------------- */

  function clamp(v, a, b) {
    return v < a ? a : (v > b ? b : v);
  }

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function invlerp(a, b, v) {
    return clamp((v - a) / (b - a || 1e-6), 0, 1);
  }

  function smoothstep(a, b, v) {
    const t = invlerp(a, b, v);
    return t * t * (3 - 2 * t);
  }

  /* ----------------------------------------------------------
     EASING
     ---------------------------------------------------------- */

  function easeInOut(t) {
    return t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
  }

  function easeOut(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  function easeIn(t) {
    return t * t * t;
  }

  /* Exponential damping — frame-rate independent */
  function damp(cur, tgt, lambda, dt) {
    return lerp(cur, tgt, 1 - Math.exp(-lambda * dt));
  }

  /* ----------------------------------------------------------
     SINE LOOKUP TABLE
     ------------------------------------------------------------
     Replaces Math.sin() with a faster table lookup.
     Accuracy is ~0.03% which is more than enough for wave motion.
     ---------------------------------------------------------- */

  const SIN_TABLE_SIZE = 2048;
  const SIN_TABLE = new Float32Array(SIN_TABLE_SIZE);
  const SIN_RANGE = SIN_TABLE_SIZE / (Math.PI * 2);

  for (let i = 0; i < SIN_TABLE_SIZE; i++) {
    SIN_TABLE[i] = Math.sin(i / SIN_RANGE);
  }

  function fastSin(x) {
    /* Wrap x into the table range, then look up */
    const i = ((x * SIN_RANGE) | 0) & (SIN_TABLE_SIZE - 1);
    return SIN_TABLE[i];
  }

  function fastCos(x) {
    return fastSin(x + Math.PI / 2);
  }

  /* ----------------------------------------------------------
     HASH & NOISE
     ---------------------------------------------------------- */

  function hash(n) {
    const s = Math.sin(n * 127.1) * 43758.5453123;
    return s - Math.floor(s);
  }

  function noise1(x) {
    const i = Math.floor(x);
    const f = x - i;
    const u = f * f * (3 - 2 * f);
    return lerp(hash(i), hash(i + 1), u) * 2 - 1;
  }

  function fbm(x, oct) {
    let a = .5, f = 1, s = 0;
    const o = oct || 3;
    for (let i = 0; i < o; i++) {
      s += noise1(x * f) * a;
      f *= 2.03;
      a *= .5;
    }
    return s;
  }

  /* ----------------------------------------------------------
     SEEDED RNG
     ---------------------------------------------------------- */

  function rng(seed) {
    let s = seed >>> 0 || 1;
    return function () {
      s ^= s << 13; s >>>= 0;
      s ^= s >> 17;
      s ^= s << 5;  s >>>= 0;
      return s / 4294967296;
    };
  }

  /* ----------------------------------------------------------
     LAYERED OCEAN WAVE
     ------------------------------------------------------------
     Never a single sine — always three plus drift.
     Uses fastSin for the two main components.
     ---------------------------------------------------------- */

  function waveAt(x, t, amp, freq) {
    return fastSin(x * freq + t * 0.9) * amp
         + fastSin(x * freq * 2.17 - t * 1.33) * amp * 0.42
         + fastSin(x * freq * 0.51 + t * 0.47) * amp * 0.66
         + fbm(x * freq * 0.8 + t * 0.35, 2) * amp * 0.30;
  }

  /* ----------------------------------------------------------
     CONSTANTS
     ---------------------------------------------------------- */

  const TAU = Math.PI * 2;

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.clamp      = clamp;
  window.lerp       = lerp;
  window.invlerp    = invlerp;
  window.smoothstep = smoothstep;
  window.easeInOut  = easeInOut;
  window.easeOut    = easeOut;
  window.easeIn     = easeIn;
  window.damp       = damp;
  window.fastSin    = fastSin;
  window.fastCos    = fastCos;
  window.hash       = hash;
  window.noise1     = noise1;
  window.fbm        = fbm;
  window.rng        = rng;
  window.waveAt     = waveAt;
  window.TAU        = TAU;

})();

/* ============================================================
   FISHKAL — Stage
   ------------------------------------------------------------
   Canvas sizing, DPR, scroll engine, vignette & grain caches.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     DOM
     ---------------------------------------------------------- */

  const stage   = document.getElementById('stage');
  const cv      = document.getElementById('world');
  const ctx     = cv.getContext('2d', { alpha: false });
  const ov      = document.getElementById('ov');
  const spacer  = document.getElementById('spacer');

  /* ----------------------------------------------------------
     STATE
     ---------------------------------------------------------- */

  let W = 0;
  let H = 0;
  let DPR = 1;

  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* Quality levels:
       2 = full (all particles, all bands, all subdivisions)
       1 = reduced (half particles, fewer bands)
       0 = minimum (no particles, no grain, minimal layers) */
  let quality = reduced ? 1 : 2;

  const SCREENS = (window.FK && window.FK.screens) || 13;

  /* Scroll state */
  let locked    = true;
  let rawP      = 0;
  let P         = 0;
  let lastScrollY = 0;

  /* Caches */
  let vig       = null;
  let grainTile = null;
  let grainLayer = null;

  /* ----------------------------------------------------------
     SIZING
     ---------------------------------------------------------- */

  function setSize() {
    const r = stage.getBoundingClientRect();
    W = Math.max(1, Math.round(r.width));
    H = Math.max(1, Math.round(r.height));

    const cap = quality >= 2 ? 2.25 : 1.35;
    DPR = Math.min(window.devicePixelRatio || 1, cap);

    cv.width  = Math.round(W * DPR);
    cv.height = Math.round(H * DPR);
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    ov.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    ov.setAttribute('width',  W);
    ov.setAttribute('height', H);

    layoutScroll();
    buildVignette();
    buildGrain();

    if (window.layoutHud) window.layoutHud();
  }

  /* ----------------------------------------------------------
     SCROLL ENGINE
     ------------------------------------------------------------
     The game lock is enforced by shortening the scroll spacer,
     so the browser itself cannot scroll past — reliable in
     iOS Safari, Android Chrome and Telegram WebView.
     ---------------------------------------------------------- */

  function layoutScroll() {
    const range = H * (SCREENS - 1);
    const h = H + (locked ? (window.TL ? window.TL.LOCK * range : 0.6 * range) : range);
    spacer.style.height = h + 'px';
  }

  function readScroll() {
    const range = H * (SCREENS - 1);
    rawP = clamp(window.scrollY / range, 0, 1);
  }

  function unlockScroll() {
    if (!locked) return;
    locked = false;
    layoutScroll();
    const cont = document.getElementById('continue');
    if (cont) {
      cont.style.opacity = '1';
      setTimeout(() => { cont.style.opacity = '0'; }, 5200);
    }
  }

  /* Re-engage the game lock (used when the experience restarts) */
  function lockScroll() {
    locked = true;
    layoutScroll();
  }

  /* ----------------------------------------------------------
     VIGNETTE CACHE
     ---------------------------------------------------------- */

  function buildVignette() {
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;

    const g = c.getContext('2d');
    const rg = g.createRadialGradient(
      W * 0.5, H * 0.48, Math.min(W, H) * 0.22,
      W * 0.5, H * 0.5,  Math.max(W, H) * 0.78
    );
    rg.addColorStop(0,    'rgba(2,9,13,0)');
    rg.addColorStop(0.62, 'rgba(2,9,13,.22)');
    rg.addColorStop(1,    'rgba(2,9,13,.78)');
    g.fillStyle = rg;
    g.fillRect(0, 0, W, H);

    vig = c;
  }

  /* ----------------------------------------------------------
     GRAIN
     ------------------------------------------------------------
     Two layers:
       grainTile  — a repeating pattern (used when quality = 2)
       grainLayer — a full-screen single draw (used when quality = 1)
     ---------------------------------------------------------- */

  function buildGrain() {
    /* Small tile */
    const s = 128;
    const c = document.createElement('canvas');
    c.width = s;
    c.height = s;
    const g = c.getContext('2d');
    const img = g.createImageData(s, s);
    for (let i = 0; i < s * s; i++) {
      const v = Math.random() * 255 | 0;
      img.data[i * 4]     = v;
      img.data[i * 4 + 1] = v;
      img.data[i * 4 + 2] = v;
      img.data[i * 4 + 3] = Math.random() * 26 | 0;
    }
    g.putImageData(img, 0, 0);
    grainTile = ctx.createPattern(c, 'repeat');

    /* Full-screen layer for lower-quality mode */
    const lc = document.createElement('canvas');
    lc.width = W + 130;
    lc.height = H + 130;
    const lg = lc.getContext('2d');
    const limg = lg.createImageData(lc.width, lc.height);
    for (let i = 0; i < limg.data.length; i += 4) {
      const v = Math.random() * 255 | 0;
      limg.data[i]     = v;
      limg.data[i + 1] = v;
      limg.data[i + 2] = v;
      limg.data[i + 3] = Math.random() * 26 | 0;
    }
    lg.putImageData(limg, 0, 0);
    grainLayer = lc;
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.stage = stage;
  window.cv    = cv;
  window.ctx   = ctx;
  window.ov    = ov;

  window.getW  = () => W;
  window.getH  = () => H;
  window.getDPR = () => DPR;
  window.getQuality = () => quality;
  window.setQuality = q => { quality = q; };

  window.isReduced = () => reduced;
  window.isLocked  = () => locked;
  window.unlockScroll = unlockScroll;
  window.lockScroll   = lockScroll;

  window.readScroll = readScroll;
  window.layoutScroll = layoutScroll;
  window.setSize = setSize;

  window.getVig = () => vig;
  window.getGrain = () => grainTile;
  window.getGrainLayer = () => grainLayer;
  window.rebuildCaches = () => { buildVignette(); buildGrain(); };

  /* ----------------------------------------------------------
     SCROLL STATE GETTERS/SETTERS
     ---------------------------------------------------------- */

  Object.defineProperty(window, 'W', { get: () => W });
  Object.defineProperty(window, 'H', { get: () => H });
  Object.defineProperty(window, 'DPR', { get: () => DPR });
  Object.defineProperty(window, 'rawP', {
    get: () => rawP,
    set: v => { rawP = clamp(v, 0, 1); }
  });
  Object.defineProperty(window, 'P', {
    get: () => P,
    set: v => { P = clamp(v, 0, 1); }
  });

})();

/* ============================================================
   FISHKAL — UI
   ------------------------------------------------------------
   Captions, result card, brand section, HUD visibility,
   depth veil and business bar integration.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     DOM CACHE
     ---------------------------------------------------------- */

  const ui = {
    hero:     document.getElementById('hero'),
    hint:     document.getElementById('hint'),
    cap:      document.getElementById('caption'),
    capBig:   document.querySelector('#caption .big'),
    capSm:    document.querySelector('#caption .small'),
    cue:      document.getElementById('cue'),
    result:   document.getElementById('result'),
    brand:    document.getElementById('brand'),
    cont:     document.getElementById('continue'),
    capIdx:   -1
  };

  const strikeBtn = document.getElementById('strike');

  /* ----------------------------------------------------------
     SCENE CAPTIONS
     ---------------------------------------------------------- */

  const CAPS = [
    { a: 0.085, b: 0.170, big: 'Leaving the coast',  sm: 'Dubai 25.20°N 55.27°E' },
    { a: 0.205, b: 0.300, big: 'The vessel',         sm: 'Dubai fishing boat' },
    { a: 0.340, b: 0.430, big: 'Dubai',              sm: 'Working ground' },
    { a: 0.470, b: 0.560, big: 'Descent',            sm: '' }
  ];

  /* ----------------------------------------------------------
     UPDATE UI
     ---------------------------------------------------------- */

  function updateUI(p) {
    const T = window.T;
    const gHud = document.getElementById('gHud');

    /* Hero fade out */
    const heroA = 1 - smoothstep(0, 0.05, p);
    if (ui.hero) ui.hero.style.opacity = heroA;

    /* Scroll hint fade */
    if (ui.hint) ui.hint.style.opacity = (1 - smoothstep(0, 0.03, p)) * 0.9;

    /* Caption */
    let idx = -1;
    let a = 0;
    for (let i = 0; i < CAPS.length; i++) {
      const c = CAPS[i];
      if (p >= c.a - 0.03 && p <= c.b + 0.03) {
        idx = i;
        a = smoothstep(c.a - 0.03, c.a + 0.01, p) *
            (1 - smoothstep(c.b - 0.01, c.b + 0.03, p));
        break;
      }
    }

    if (idx !== ui.capIdx) {
      ui.capIdx = idx;
      if (idx >= 0 && ui.capBig && ui.capSm) {
        ui.capBig.textContent = T(CAPS[idx].big);
        ui.capSm.textContent = T(CAPS[idx].sm);
      }
    }

    if (ui.cap) ui.cap.style.opacity = idx >= 0 ? a : 0;

    /* HUD */
    if (gHud) {
      const hudA = smoothstep(0.54, 0.62, p) * (1 - smoothstep(0.78, 0.86, p)) * 0.65;
      gHud.setAttribute('opacity', hudA.toFixed(3));
    }

    /* Result card fade out after ascent */
    if (window.Game) {
      const gs = window.Game.state;
      if ((gs === 'RESULT_SHOWN' || gs === 'UNLOCK') && p > 0.655) {
        if (ui.result) ui.result.classList.remove('on');
      }
    }

    /* Brand section */
    const brandOn = p > 0.925;
    if (ui.brand) ui.brand.classList.toggle('on', brandOn);

    /* Depth veil */
    const veil = document.getElementById('depthVeil');
    if (veil && window.cam) {
      const d = window.cam.depth;
      const op = Math.max(0, Math.min(1, (d - 0.25) * 1.15)) * 0.9;
      veil.style.opacity = op.toFixed(3);
    }
  }

  /* ----------------------------------------------------------
     RESULT DISMISS
     ---------------------------------------------------------- */

  function dismissResult(via) {
    if (ui.result) ui.result.classList.remove('on');
    if (window.Game && window.Game.state === 'RESULT_SHOWN') {
      window.Game.state = 'UNLOCK';
      try { window.unlockScroll(); } catch (e) {}
    }
  }

  function initResultDismiss() {
    if (document.getElementById('resClose')) return;
    const rc = document.createElement('button');
    rc.id = 'resClose';
    rc.type = 'button';
    rc.textContent = '×';
    rc.setAttribute('aria-label', 'Close result');
    if (ui.result) ui.result.appendChild(rc);

    /* pointerdown = instant on touch; click covers keyboard (Enter/Space) */
    const close = (e) => { if (e) e.preventDefault(); dismissResult('btn'); };
    rc.addEventListener('pointerdown', close);
    rc.addEventListener('click', close);
  }

  /* ----------------------------------------------------------
     BOOT SCREEN
     ---------------------------------------------------------- */

  function initBootScreen() {
    if (document.getElementById('boot')) return;
    const boot = document.createElement('div');
    boot.id = 'boot';
    boot.innerHTML =
      '<div style="text-align:center">' +
        '<div class="w">Fishkal</div>' +
        '<div class="l"></div>' +
      '</div>';
    document.body.appendChild(boot);

    window.addEventListener('load', () => {
      setTimeout(() => boot.classList.add('off'), 700);
    });

    setTimeout(() => boot.classList.add('off'), 4000);
  }

  /* ----------------------------------------------------------
     DEPTH VEIL
     ---------------------------------------------------------- */

  function initDepthVeil() {
    if (document.getElementById('depthVeil')) return;
    const veil = document.createElement('div');
    veil.id = 'depthVeil';
    document.body.appendChild(veil);
  }

  /* ----------------------------------------------------------
     TRACKING HELPER
     ---------------------------------------------------------- */

  function track(event, props) {
    props = props || {};

    if (window.plausible && window.FK && window.FK.plausibleDomain) {
      window.plausible(event, { props });
    }

    if (window.gtag && window.FK && window.FK.gaId) {
      window.gtag('event', event, props);
    }
  }

  /* ----------------------------------------------------------
     ANALYTICS INIT
     ---------------------------------------------------------- */

  function initAnalytics() {
    if (!window.FK) return;

    /* Plausible */
    if (window.FK.plausibleDomain) {
      const s = document.createElement('script');
      s.defer = true;
      s.dataset.domain = window.FK.plausibleDomain;
      s.src = 'https://plausible.io/js/script.js';
      document.head.appendChild(s);
    }

    /* GA4 */
    if (window.FK.gaId) {
      const s = document.createElement('script');
      s.async = true;
      s.src = 'https://www.googletagmanager.com/gtag/js?id=' + window.FK.gaId;
      document.head.appendChild(s);

      window.dataLayer = window.dataLayer || [];
      window.gtag = function () { window.dataLayer.push(arguments); };
      window.gtag('js', new Date());
      window.gtag('config', window.FK.gaId);
    }
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.ui = ui;
  window.updateUI = updateUI;
  window.track = track;

  window.initResultDismiss = initResultDismiss;
  window.dismissResult = dismissResult;
  window.initBootScreen = initBootScreen;
  window.initDepthVeil = initDepthVeil;
  window.initAnalytics = initAnalytics;

  window.strikeBtn = strikeBtn;

})();

/* ============================================================
   FISHKAL — Underwater
   ------------------------------------------------------------
   Gradient background, light shafts, caustics, hull-from-below,
   seabed, waterline (meniscus), and particle systems.
   ============================================================ */

(function () {
  'use strict';

  /* ----------------------------------------------------------
     CAMERA REFERENCE
     ---------------------------------------------------------- */

  /* cam is owned by main.js but exposed on window */
  function cam() { return window.cam; }

  /* ----------------------------------------------------------
     UNDERWATER SCENE
     ---------------------------------------------------------- */

  function drawUnderwater(t) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;
    const q = window.getQuality();
    const c = cam();

    const d = c.depth;
    const top = Math.max(c.meniscusY, -H * 0.3);

    const g = ctx.createLinearGradient(0, top, 0, H);
    g.addColorStop(0,    `rgb(${lerp(26, 7, d) | 0},${lerp(140, 72, d) | 0},${lerp(146, 88, d) | 0})`);
    g.addColorStop(0.28, `rgb(${lerp(12, 4, d) | 0},${lerp(92, 42, d) | 0},${lerp(112, 60, d) | 0})`);
    g.addColorStop(0.68, `rgb(${lerp(6, 2, d) | 0},${lerp(52, 18, d) | 0},${lerp(70, 30, d) | 0})`);
    g.addColorStop(1,    `rgb(${lerp(3, 1, d) | 0},${lerp(24, 7, d) | 0},${lerp(28, 13, d) | 0})`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);

    /* Light shafts */
    ctx.globalCompositeOperation = 'lighter';
    const shafts = q >= 2 ? 7 : 4;
    const originX = c.sunX;
    const originY = Math.min(c.meniscusY, H * 0.02) - H * 0.25;

    for (let i = 0; i < shafts; i++) {
      const ph = i * 1.7;
      const sway = Math.sin(t * 0.28 + ph) * W * 0.045 + fbm(t * 0.16 + ph, 2) * W * 0.02;
      const x0 = originX + (i - (shafts - 1) / 2) * W * 0.10 + sway;
      const wTop = W * 0.018;
      const wBot = W * (0.10 + 0.03 * Math.sin(t * 0.2 + ph));

      const lg = ctx.createLinearGradient(0, originY, 0, H * 1.02);
      const a = (0.085 - i * 0.006) * lerp(1, 0.10, d);
      lg.addColorStop(0,    `rgba(190,255,238,${a})`);
      lg.addColorStop(0.45, `rgba(140,226,214,${a * 0.55})`);
      lg.addColorStop(1,    'rgba(120,200,190,0)');

      ctx.fillStyle = lg;
      ctx.beginPath();
      ctx.moveTo(x0 - wTop, originY);
      ctx.lineTo(x0 + wTop, originY);
      ctx.lineTo(x0 + wBot, H * 1.02);
      ctx.lineTo(x0 - wBot, H * 1.02);
      ctx.closePath();
      ctx.fill();
    }
    ctx.globalCompositeOperation = 'source-over';

    /* Caustics near the surface */
    if (c.meniscusY > -H * 0.2 && c.meniscusY < H * 1.1) {
      const my = c.meniscusY;
      ctx.globalCompositeOperation = 'lighter';
      const bands = q >= 2 ? 9 : 5;
      for (let i = 0; i < bands; i++) {
        const y = my + i * H * 0.030 + Math.sin(t * 0.8 + i) * 2;
        if (y < -20 || y > H + 20) continue;
        const a = (0.16 - i * 0.017) * lerp(1, 0.15, d);
        if (a <= 0) continue;
        ctx.strokeStyle = `rgba(210,255,240,${a})`;
        ctx.lineWidth = lerp(2.4, 0.8, i / bands);
        ctx.beginPath();
        for (let x = -10; x <= W + 10; x += 10) {
          const yy = y + waveAt(x, t * 1.2 + i * 0.6, 6 + i, 0.028);
          x === -10 ? ctx.moveTo(x, yy) : ctx.lineTo(x, yy);
        }
        ctx.stroke();
      }
      ctx.globalCompositeOperation = 'source-over';

      /* Hull from below */
      if (c.depth < 0.55) {
        ctx.save();
        ctx.globalAlpha = (1 - smoothstep(0.15, 0.55, c.depth)) * 0.75;
        ctx.translate(c.hullX, my - H * 0.02);
        const s = c.hullS;
        ctx.scale(s, s * 0.62);
        window.boatHullPath(ctx);
        ctx.fillStyle = '#04161c';
        ctx.fill();
        ctx.strokeStyle = 'rgba(150,220,210,.35)';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
        ctx.globalAlpha = 1;
      }
    }

    /* Seabed */
    const sb = smoothstep(0.55, 0.92, d);
    if (sb > 0) {
      ctx.save();
      ctx.globalAlpha = sb;
      const by = H * 0.94;
      ctx.beginPath();
      ctx.moveTo(0, H);
      ctx.lineTo(0, by);
      for (let x = 0; x <= W; x += 18) {
        ctx.lineTo(x, by - Math.abs(fbm(x * 0.006 + 3.2, 3)) * H * 0.055);
      }
      ctx.lineTo(W, H);
      ctx.closePath();
      const lg = ctx.createLinearGradient(0, by - H * 0.06, 0, H);
      lg.addColorStop(0, '#06222b');
      lg.addColorStop(1, '#020c12');
      ctx.fillStyle = lg;
      ctx.fill();

      const R = rng(4412);
      for (let i = 0; i < 9; i++) {
        const x = R() * W;
        const r = W * (0.02 + R() * 0.05);
        ctx.beginPath();
        ctx.ellipse(x, by + r * 0.2, r, r * 0.5, 0, Math.PI, 0);
        ctx.fillStyle = '#041a22';
        ctx.fill();
      }
      ctx.restore();
    }
  }

  /* ----------------------------------------------------------
     WATERLINE (MENISCUS)
     ---------------------------------------------------------- */

  function waterlinePath(y, t, toTop) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;

    ctx.beginPath();
    const amp = lerp(3, 22, clamp(1 - Math.abs(y - H * 0.5) / (H * 0.6), 0, 1));
    ctx.moveTo(-20, y + waveAt(-20, t, amp, 0.018));
    for (let x = -20; x <= W + 20; x += 10) {
      ctx.lineTo(x, y + waveAt(x, t, amp, 0.018));
    }
    if (toTop) {
      ctx.lineTo(W + 20, -40);
      ctx.lineTo(-20, -40);
    } else {
      ctx.lineTo(W + 20, H + 40);
      ctx.lineTo(-20, H + 40);
    }
    ctx.closePath();
  }

  function drawMeniscus(t) {
    const ctx = window.ctx;
    const W = window.W;
    const H = window.H;
    const c = cam();
    const y = c.meniscusY;
    if (y < -30 || y > H + 30) return;

    ctx.save();

    const amp = lerp(3, 22, clamp(1 - Math.abs(y - H * 0.5) / (H * 0.6), 0, 1));

    const lg = ctx.createLinearGradient(0, y - H * 0.02, 0, y + H * 0.05);
    lg.addColorStop(0,    'rgba(255,232,196,.30)');
    lg.addColorStop(0.28, 'rgba(180,240,230,.22)');
    lg.addColorStop(1,    'rgba(180,240,230,0)');
    ctx.fillStyle = lg;
    waterlinePath(y, t, false);
    ctx.fill();

    ctx.beginPath();
    for (let x = -20; x <= W + 20; x += 8) {
      const yy = y + waveAt(x, t, amp, 0.018);
      x === -20 ? ctx.moveTo(x, yy) : ctx.lineTo(x, yy);
    }
    ctx.strokeStyle = 'rgba(255,240,214,.62)';
    ctx.lineWidth = 1.6;
    ctx.stroke();

    ctx.restore();
  }

  /* ----------------------------------------------------------
     PARTICLES (pooled)
     ---------------------------------------------------------- */

  const snow = [];
  const bub = [];

  function initParticles() {
    snow.length = 0;
    bub.length = 0;

    const W = window.W;
    const H = window.H;
    const q = window.getQuality();

    const n = q >= 2 ? 130 : 60;
    const R = rng(555);

    for (let i = 0; i < n; i++) {
      snow.push({
        x: R() * W,
        y: R() * H,
        z: 0.25 + R() * 0.9,
        s: 0.6 + R() * 1.9,
        p: R() * TAU,
        v: 2 + R() * 9
      });
    }

    for (let i = 0; i < 48; i++) {
      bub.push({ on: false, x: 0, y: 0, r: 0, v: 0, p: 0, a: 0 });
    }
  }

  function spawnBubbles(x, y, count, power) {
    let made = 0;
    for (let i = 0; i < bub.length && made < count; i++) {
      const b = bub[i];
      if (b.on) continue;
      b.on = true;
      b.x = x + (Math.random() - 0.5) * 26 * power;
      b.y = y + (Math.random() - 0.5) * 18;
      b.r = 1.4 + Math.random() * 4.6 * power;
      b.v = 16 + Math.random() * 52 * power;
      b.p = Math.random() * TAU;
      b.a = 1;
      made++;
    }
  }

  function updateParticles(dt, t) {
    const H = window.H;
    const W = window.W;

    for (const s of snow) {
      s.y -= s.v * s.z * dt * 0.35;
      if (s.y < -6) {
        s.y = H + 6;
        s.x = Math.random() * W;
      }
    }

    for (const b of bub) {
      if (!b.on) continue;
      b.y -= b.v * dt;
      b.a -= dt * 0.5;
      if (b.a <= 0 || b.y < -20) b.on = false;
    }
  }

  function drawParticles(t) {
    const ctx = window.ctx;

    ctx.globalCompositeOperation = 'lighter';

    for (const s of snow) {
      const x = s.x + Math.sin(t * 0.5 + s.p) * 8 * s.z;
      ctx.fillStyle = `rgba(200,240,232,${0.05 + s.z * 0.13})`;
      ctx.fillRect(x, s.y, s.s * s.z, s.s * s.z);
    }

    for (const b of bub) {
      if (!b.on) continue;
      const x = b.x + Math.sin(t * 3 + b.p) * 5;
      ctx.beginPath();
      ctx.arc(x, b.y, b.r, 0, TAU);
      ctx.strokeStyle = `rgba(210,248,242,${0.42 * b.a})`;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = `rgba(190,240,236,${0.10 * b.a})`;
      ctx.fill();
    }

    ctx.globalCompositeOperation = 'source-over';
  }

  /* ----------------------------------------------------------
     EXPORT
     ---------------------------------------------------------- */

  window.drawUnderwater = drawUnderwater;
  window.waterlinePath = waterlinePath;
  window.drawMeniscus = drawMeniscus;
  window.initParticles = initParticles;
  window.spawnBubbles = spawnBubbles;
  window.updateParticles = updateParticles;
  window.drawParticles = drawParticles;

  window.snow = snow;
  window.bub = bub;

})();
